local function generateConfigH()
    local vars = {
        COOST_SHARED          = "0",
        CACHE_LINE_SIZE       = "64",
        PROJECT_VERSION_MAJOR = "3",
        PROJECT_VERSION_MINOR = "0",
        PROJECT_VERSION_PATCH = "0",
    }

    local inPath  ="coost/include/co/config.h.in"
    local outPath ="coost/include/co/config.h"

    local inFile = io.open(inPath, "r")
    if not inFile then
        -- Write a minimal fallback if the template is missing
        print("[premake] WARNING: config.h.in not found, writing fallback config.h")
        local f = io.open(outPath, "w")
        f:write("// Auto-generated by premake5.lua\n")
        f:write("#pragma once\n")
        f:write("#define COOST_SHARED 1\n")
        f:write("#ifndef L1_CACHE_LINE_SIZE\n")
        f:write("#define L1_CACHE_LINE_SIZE 64\n")
        f:write("#endif\n")
        f:close()
        return
    end

    local content = inFile:read("*a")
    inFile:close()

    -- 1. ${VAR} style
    content = content:gsub("%${([A-Za-z0-9_]+)}", function(k)
        return vars[k] ~= nil and vars[k] or "${" .. k .. "}"
    end)

    -- 2. @VAR@ style
    content = content:gsub("@([A-Za-z0-9_]+)@", function(k)
        return vars[k] ~= nil and vars[k] or "@" .. k .. "@"
    end)

    -- 3. #cmakedefine01 VAR
    content = content:gsub("#cmakedefine01%s+([A-Za-z0-9_]+)", function(k)
        return "#define " .. k .. " " .. (vars[k] or "0")
    end)

    -- 4. #cmakedefine VAR
    content = content:gsub("#cmakedefine%s+([A-Za-z0-9_]+)", function(k)
        local v = vars[k]
        if v and v ~= "0" and v ~= "" then
            return "#define " .. k
        end
        return "/* #undef " .. k .. " */"
    end)

    local outFile = io.open(outPath, "w")
    outFile:write("// Auto-generated by premake5.lua – do not edit manually.\n")
    outFile:write(content)
    outFile:close()
    print("[premake] Generated " .. outPath)
end

generateConfigH()

project "coost"
    kind       "StaticLib"
    language   "C++"
    cppdialect "C++11"
 	warnings "off"
   	architecture "x64"

   	targetdir ("../bin/" .. outputdir .. "/%{prj.name}")
   	objdir ("../bin/inter/" .. outputdir .. "/%{prj.name}")
    
    includedirs { "coost/include" }

    files { "coost/src/**.cc" }

    filter { "action:vs*", "platforms:x64" }
        files { "coost/src/co/context/context_x64.asm" }
    filter { "action:vs*", "platforms:x86" }
        files { "coost/src/co/context/context_x86.asm" }
    filter "system:not windows"
        files { "coost/src/co/context/context.S" }

    filter "system:windows"
        files {
            "coost/src/log/StackWalker.cpp",
            "coost/src/co/detours/creatwth.cpp",
            "coost/src/co/detours/detours.cpp",
            "coost/src/co/detours/image.cpp",
            "coost/src/co/detours/modules.cpp",
            "coost/src/co/detours/disasm.cpp",
        }

    filter "system:macosx"
        files { "coost/src/co/fishhook/fishhook.c" }

    filter "system:windows"
        defines {
            "WIN32_LEAN_AND_MEAN",
            "_WINSOCK_DEPRECATED_NO_WARNINGS",
        }

    filter { "system:macosx", "action:not vs*" }
        buildoptions { "-fno-pie" }

    filter "system:windows"
        links { "ws2_32" }

    filter "system:linux"
        links { "pthread", "dl" }

    filter "system:macosx"
        links { "pthread" }

	filter "configurations:Debug"
       defines { "DEBUG" }
       runtime "Debug"
       symbols "On"

    filter "configurations:Release"
       defines { "RELEASE", "_DISABLE_CONSTEXPR_MUTEX_CONSTRUCTOR" }
       runtime "Release"
       optimize "On"
       symbols "On"

    filter "configurations:Dist"
       defines { "DIST", "_DISABLE_CONSTEXPR_MUTEX_CONSTRUCTOR" }
       runtime "Release"
       optimize "On"
       symbols "Off"